class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int n = prices.size();
        int maxProfit = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int profit = prices[j] - prices[i];
                if (profit > maxProfit) {
                    maxProfit = profit;
                }
            }
        }
        return maxProfit;
    }
};

#include <vector>
#include <algorithm>

class Solution {
public:
    int maxProfit(std::vector<int>& prices) {
        int n = prices.size();
        if (n == 0) return 0;

        int minSoFar = prices[0];
        int maxProfit = 0;

        for (int i = 1; i < n; i++) {
            // Update cheapest price seen so far
            minSoFar = std::min(minSoFar, prices[i]);

            // Compute profit if selling today and update maximum
            maxProfit = std::max(maxProfit, prices[i] - minSoFar);
        }
        return maxProfit;
    }
};
